-- Migration: Year 2 - Sexual & Forensic Pathology MCQs Part 2 (39-75)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Sexual & Forensic Pathology', 'sexual-forensic-pathology', 3, 2, 62)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- TESTICULAR PATHOLOGY: NON-NEOPLASTIC (39-46)
    (v_topic_id, 'Cryptorchidism (undescended testis) is the most common congenital genitourinary anomaly in males. What is the most significant long-term risk?', '["Infertility from mechanical obstruction only", "Testicular malignancy (especially seminoma) — risk is 4-10x higher than general population, even in the contralateral normally descended testis; also causes infertility from failed spermatogenesis", "Inguinal hernia strangulation", "Epididymitis exclusively"]', 1, 'Cryptorchidism: the testis fails to descend into the scrotum (usually arrests in the inguinal canal). Abdominal temperature (37C) impairs spermatogenesis (optimal: 34-35C) and increases cancer risk. Orchiopexy before age 2 restores fertility potential and allows palpation for tumor surveillance but does not eliminate cancer risk.'),
    (v_topic_id, 'Testicular torsion is a urological emergency. What is the most important anatomical predisposing factor?', '["Epididymis attached anteriorly", "Bell-clapper deformity: high attachment of the tunica vaginalis around the spermatic cord rather than posterolaterally, allowing the testis to rotate freely like a bell clapper", "Short vas deferens", "Absent gubernaculum"]', 1, 'Bell-clapper deformity allows the testis to swing and rotate within the tunica vaginalis, twisting the spermatic cord and its vasculature. It is bilateral in ~80% of cases — contralateral orchiopexy is performed simultaneously. Peak age: 12-18 years (pubescent testis enlargement increases rotational momentum).'),
    (v_topic_id, 'Testicular torsion presents with sudden onset scrotal pain. The cremasteric reflex is absent. What is the time window for salvage?', '["24-48 hours", "Within 6 hours (near 100% salvage rate); salvage rate drops to ~50% at 12-24 hours and near 0% at >24 hours", "Within 72 hours", "Time is not critical — the testis can tolerate prolonged ischemia"]', 1, 'Testicular torsion causes venous obstruction first, then arterial occlusion → ischemia → infarction. Salvage rates: <6 hours >95%; 6-12 hours ~75%; 12-24 hours ~50%; >24 hours <10%. Diagnosis: clinical (sudden pain + absent cremasteric reflex + high-riding testis). Doppler ultrasound if diagnosis uncertain. Do NOT delay surgery for imaging if clinical diagnosis is clear.'),
    (v_topic_id, 'Orchitis from mumps occurs in post-pubertal males. What is the consequence of bilateral mumps orchitis?', '["Testicular cancer", "Infertility from bilateral testicular atrophy (granulomatous inflammation destroys seminiferous tubules, impairing spermatogenesis — Leydig cells usually preserved, so testosterone is normal)", "Bilateral hydrocele formation", "Epididymal cyst formation"]', 1, 'Mumps orchitis: occurs in 20-30% of post-pubertal males with mumps. Bilateral in ~15% → bilateral testicular atrophy → azoospermia and infertility. Leydig cells are more resistant, so testosterone and virilization are usually preserved. MMR vaccination prevents mumps and thus mumps orchitis.'),
    (v_topic_id, 'Epididymitis in young sexually active men is most commonly caused by?', '["Escherichia coli", "Chlamydia trachomatis (most common in men <35) followed by Neisseria gonorrhoeae", "Pseudomonas aeruginosa", "Staphylococcus aureus"]', 1, 'Epididymitis in sexually active young men: Chlamydia trachomatis > N. gonorrhoeae. In older men (>35) or those with recent urologic instrumentation: E. coli and other gram-negative enteric organisms. Presents as gradual unilateral scrotal pain, swelling, and tenderness. Cremasteric reflex is INTACT (distinguishes from torsion). Treat: ceftriaxone + doxycycline.'),
    (v_topic_id, 'A varicocele is an abnormal dilation of the pampiniform plexus of veins. Which side is almost always affected?', '["Right side predominantly", "Left side predominantly (>90%) due to the left testicular vein draining perpendicularly into the left renal vein (creating higher venous back-pressure), unlike the right which drains obliquely into the IVC", "Both sides equally", "Bilateral in 50% of cases"]', 1, 'Left varicocele predominance: left testicular vein drains at a right angle into the left renal vein (high pressure), while the right drains obliquely into the IVC (lower pressure). A right-sided or new left-sided varicocele in an older man should prompt renal ultrasound to exclude left renal vein compression by RCC (nutcracker phenomenon).'),
    (v_topic_id, 'A hydrocele is an accumulation of fluid between the layers of the tunica vaginalis. How is it distinguished from a solid testicular mass?', '["By MRI", "By transillumination: a hydrocele transilluminates (light passes through fluid freely); solid tumors do not transilluminate. Confirmed by ultrasound.", "By measuring AFP and beta-hCG", "By surgical exploration only"]', 1, 'Hydrocele: fluid in the potential space of the tunica vaginalis. Transillumination test: shine a bright light through the scrotum — hydrocele glows red (light transmits through fluid). A solid mass does not transilluminate. Always perform scrotal ultrasound in adults with new hydrocele to exclude an underlying testicular tumor (tumors can cause reactive hydrocele).'),
    (v_topic_id, 'A spermatocele is a cystic structure found above and posterior to the testis, arising from the epididymis. It contains?', '["Whole blood (hematocele)", "Spermatozoa and serous fluid — a retention cyst of the epididymis. Palpable as a soft, transilluminable cystic mass distinct from and superior to the testis", "Lymph fluid", "Urine from an ectopic ureter"]', 1, 'Spermatocele: epididymal retention cyst containing dead sperm and protein-rich fluid. On transillumination, the fluid appears milky/opalescent (unlike clear hydrocele fluid). Located above and behind the testis (epididymis position). Benign — no treatment unless symptomatic. Microscopically: sperm heads can be seen in the aspirated fluid.'),

    -- TESTICULAR TUMORS: GERM CELL (47-64)
    (v_topic_id, 'Testicular germ cell tumors (GCTs) are the most common solid malignancy in men aged 15-35. What is the initial workup?', '["Immediate surgical scrotal exploration with biopsy", "Serum tumor markers (AFP, beta-hCG, LDH) + scrotal ultrasound. Radical orchiectomy via inguinal approach (NEVER transscrotal biopsy — risks lymphatic spread to inguinal nodes instead of retroperitoneal)", "Transurethral biopsy", "CT scan alone without markers"]', 1, 'Testicular cancer workup: (1) Serum AFP, beta-hCG, LDH before surgery (baseline for staging and monitoring); (2) Scrotal ultrasound (confirms intratesticular mass); (3) Radical inguinal orchiectomy (via inguinal incision with early high ligation of spermatic cord to prevent lymphovascular spread). Transscrotal approach is contraindicated (disrupts lymphatics → inguinal node metastasis).'),
    (v_topic_id, 'Seminoma is the most common testicular GCT. What are its characteristic features?', '["Elevated AFP and beta-hCG, responds poorly to radiation", "Uniform sheets of large cells with clear cytoplasm, central nuclei with prominent nucleoli, fibrous septa with lymphocytes — AFP negative, beta-hCG mildly elevated in some cases, highly radiosensitive", "Heterogeneous tumor with cartilage and hair (teratoma)", "Multinucleated syncytiotrophoblasts with high beta-hCG"]', 1, 'Seminoma: peak age 35-45. Large cells with clear cytoplasm (glycogen-rich), central nucleus with prominent nucleolus, separated by fibrous septa containing lymphocytes and granulomas. AFP is NEVER elevated in pure seminoma (if AFP is elevated, it is a non-seminomatous GCT by definition). Excellent prognosis (95%+ cure rate). Highly radiosensitive and chemosensitive.'),
    (v_topic_id, 'Embryonal Carcinoma is a highly malignant NSGCT. What are its histological features and tumor markers?', '["Uniform cells with clear cytoplasm; AFP negative, beta-hCG negative", "Primitive pleomorphic cells forming glands, tubules, or solid sheets resembling early embryonic epithelium; AFP and/or beta-hCG may be elevated; highly aggressive with early vascular invasion", "Schiller-Duval bodies with AFP elevation; purely solid growth", "Trophoblastic giant cells with very high beta-hCG; hemorrhagic gross appearance"]', 1, 'Embryonal carcinoma: highly malignant, peak age 20-30. Cells look primitive and undifferentiated (like early embryo). Variable AFP and beta-hCG elevation. Tends to invade lymphatics and blood vessels early. The most common component of mixed GCTs. Treatment: BEP chemotherapy (bleomycin, etoposide, cisplatin).'),
    (v_topic_id, 'Yolk Sac Tumor (endodermal sinus tumor) is the most common testicular tumor in infants and young children. What is the pathognomonic histological structure?', '["Call-Exner bodies", "Schiller-Duval bodies: a central capillary surrounded by a cuff of columnar tumor cells, resembling the yolk sac endodermal sinus — associated with markedly elevated AFP", "Auer rods in the cytoplasm", "Rosenthal fibers"]', 1, 'Yolk Sac Tumor: peak age in children <3 years (good prognosis with surgery alone) and as a component of mixed GCTs in adults (poor prognosis). AFP is markedly elevated (diagnostic). Schiller-Duval bodies (glomeruloid structures) are pathognomonic. Also see PAS-positive hyaline droplets (AFP-containing).'),
    (v_topic_id, 'Choriocarcinoma of the testis is the most aggressive GCT. What tumor markers are elevated?', '["AFP only", "beta-hCG (markedly elevated) — syncytiotrophoblasts produce hCG; AFP is typically normal in pure choriocarcinoma", "LDH only", "AFP and beta-hCG equally elevated"]', 1, 'Choriocarcinoma: biphasic tumor with syncytiotrophoblasts (large, multinucleated, beta-hCG producing) and cytotrophoblasts. Markedly elevated beta-hCG (can cause gynecomastia from cross-reactivity with LH/FSH receptors and hyperthyroidism from cross-reactivity with TSH receptor). Hematogenous spread dominates (to lungs first) — metastases often larger than primary tumor. Poor prognosis without treatment.'),
    (v_topic_id, 'Teratoma in adult males behaves very differently from teratoma in prepubertal boys. Why?', '["Adult teratomas contain only mature tissue while children''s contain immature tissue", "In post-pubertal males, even mature teratoma is considered malignant and has metastatic potential (unlike prepubertal boys where mature teratoma is benign); treated as malignant GCT", "Adult teratomas respond to radiation; pediatric ones do not", "Teratomas produce AFP only in children"]', 1, 'In prepubertal boys (not yet through puberty), testicular teratomas are benign (orchiectomy is curative). In post-pubertal males and adults, testicular teratoma is considered malignant regardless of histological maturity — it can metastasize, often as the non-teratomatous component. Crucial for board examinations.'),
    (v_topic_id, 'A 22-year-old male has a painless testicular mass. AFP is 8000 ng/mL (normal <10). beta-hCG is normal. What is the most likely diagnosis?', '["Pure seminoma", "Non-seminomatous GCT — the elevated AFP rules out pure seminoma definitively. Likely yolk sac tumor component or mixed GCT.", "Lymphoma", "Leydig cell tumor"]', 1, 'AFP is produced by yolk sac tumor cells and is never elevated in pure seminoma. ANY elevated AFP in a testicular GCT = non-seminomatous (treated more aggressively than seminoma). Mixed GCTs (the most common testicular GCT in adults) often contain yolk sac elements elevating AFP. Treatment: radical orchiectomy + retroperitoneal lymph node dissection or BEP chemotherapy.'),
    (v_topic_id, 'Intratubular Germ Cell Neoplasia (ITGCN), also called carcinoma in situ of the testis, is the precursor to most adult GCTs. What is its clinical significance?', '["It always progresses to invasive cancer within 6 months", "ITGCN progresses to invasive GCT in ~50% of cases over 5 years — detected on biopsy of the contralateral testis; found in high-risk groups (cryptorchidism, infertility, prior GCT)", "It causes acute pain and fever", "It produces very high beta-hCG"]', 1, 'ITGCN: atypical germ cells replacing normal seminiferous tubule epithelium, with no invasion through the tubular basement membrane. Marker: PLAP (placental alkaline phosphatase) positive. In men with known risk factors (cryptorchidism, prior GCT, infertility), contralateral biopsy may be offered. Options: active surveillance, radiation (low-dose), or orchiectomy.'),
    (v_topic_id, 'The retroperitoneal lymph nodes are the first site of metastasis for testicular GCTs. Why?', '["Because of hematogenous spread through the testicular artery", "The testis develops embryologically in the retroperitoneum and descends with its lymphatic drainage intact — lymphatics follow the testicular vessels to para-aortic lymph nodes (around L1-L2)", "Because the inguinal lymph nodes block retroperitoneal spread", "Testicular cancer spreads only hematogenously"]', 1, 'Testicular lymphatics follow the gonadal vessels back to their embryological origin: para-aortic/paracaval nodes at L1-L2. This is why transscrotal biopsy is forbidden (scrotal lymphatics drain to inguinal nodes, changing the nodal drainage pattern and making treatment more complex). Right-sided tumors can cross-drain to left para-aortic nodes.'),
    (v_topic_id, 'After orchiectomy for a Stage I seminoma, what is the preferred management in most guidelines?', '["Immediate retroperitoneal lymph node dissection (RPLND)", "Active surveillance (in compliant patients) OR adjuvant single-agent carboplatin OR adjuvant para-aortic radiation — all are equivalent; surveillance preferred to minimize treatment toxicity", "Immediate BEP chemotherapy x 4 cycles", "Radiation to the whole abdomen and pelvis"]', 1, 'Stage I seminoma (confined to testis, no metastases, normal post-orchiectomy markers): excellent prognosis with any of three approaches: surveillance (avoid overtreatment; 15-20% relapse, all salvageable), single-cycle carboplatin (reduces relapse to ~5%), or adjuvant para-aortic radiation (historical). Surveillance is preferred by most modern guidelines to avoid late toxicity.'),
    (v_topic_id, 'BEP chemotherapy is the standard treatment for metastatic GCTs. What is the dose-limiting toxicity of bleomycin in this regimen?', '["Nephrotoxicity", "Pulmonary fibrosis — bleomycin causes oxidative DNA damage in pulmonary endothelium and pneumocytes, leading to progressive lung fibrosis (bleomycin lung)", "Peripheral neuropathy", "Ototoxicity"]', 1, 'Bleomycin pulmonary toxicity: cumulative dose-dependent lung injury. Manifests as pulmonary fibrosis (honeycombing on CT). Risk factors: cumulative dose >400 units, age >40, renal impairment, supplemental O2 (anesthesia with high FiO2 can precipitate acute injury). Monitor with PFTs (DLCO). Cisplatin toxicity: nephrotoxicity + ototoxicity + peripheral neuropathy.'),

    -- NON-GERM CELL TESTICULAR TUMORS (65-70)
    (v_topic_id, 'Leydig Cell Tumor is the most common sex cord-stromal tumor of the testis. What is its clinical presentation?', '["Painless testicular mass with elevated AFP", "Painless testicular mass with hormonal effects: gynecomastia in adults (excess estrogen from aromatization of testosterone) or precocious puberty in prepubertal boys (excess testosterone/estrogen)", "Testicular pain and fever", "Elevated beta-hCG and contralateral testicular atrophy"]', 1, 'Leydig cells produce testosterone (and estrogen via aromatase). Leydig cell tumors secrete excess steroids. In boys: precocious puberty (isosexual — excess testosterone). In adult men: gynecomastia and decreased libido (excess estrogen from aromatization of excess testosterone). Pathognomonic: Reinke crystals (rod-shaped crystalloid inclusions) in cytoplasm. 90% benign.'),
    (v_topic_id, 'Sertoli Cell Tumor of the testis. What is its histological hallmark?', '["Schiller-Duval bodies", "Tubular differentiation — tumor cells form tubules (resembling normal Sertoli cells lining seminiferous tubules), often with Call-Exner-like bodies or clear cytoplasm", "Auer rods in cytoplasm", "Multinucleated giant cells with central capillaries"]', 1, 'Sertoli cell tumors: form tubules with Sertoli-like cells. Most are benign. Can cause gynecomastia (estrogen secretion). Associated with Peutz-Jeghers syndrome (large cell calcifying Sertoli cell tumor). Pathology: tubular pattern with pale/clear cytoplasm, Call-Exner-like spaces. AFP and beta-hCG are negative.'),
    (v_topic_id, 'Testicular lymphoma is the most common testicular tumor in men over age 60. What is the most common type?', '["Follicular lymphoma", "Diffuse Large B-Cell Lymphoma (DLBCL) — presents as a painless testicular mass in elderly men; often bilateral; aggressive behavior and tendency to relapse in CNS and contralateral testis", "CLL/SLL", "Burkitt lymphoma"]', 1, 'Testicular DLBCL: most common testicular malignancy in men >60. Bilateral in 10-15% (unlike GCTs which are rarely bilateral). High propensity for CNS relapse → CNS prophylaxis mandatory. Treatment: R-CHOP + intrathecal methotrexate + contralateral testicular radiation.'),
    (v_topic_id, 'The gonads of intersex patients (disorders of sexual development with dysgenetic gonads) carry a high risk of which tumor?', '["Teratoma", "Gonadoblastoma — a tumor containing both germ cell and sex cord-stromal elements; occurs almost exclusively in dysgenetic gonads with Y chromosome material; 50% of gonadoblastomas contain seminoma", "Sertoli cell tumor exclusively", "Yolk sac tumor exclusively"]', 1, 'Gonadoblastoma: benign but precancerous neoplasm arising in dysgenetic gonads (streak gonads or cryptorchid testes) in patients with Y chromosome material (XY gonadal dysgenesis, androgen insensitivity syndrome). Risk of malignant GCT (seminoma, embryonal) arising within. Prophylactic gonadectomy is recommended in patients with dysgenetic gonads + Y chromosome.'),
    (v_topic_id, 'Adenomatoid Tumor is the most common benign tumor of the epididymis. What is its cell of origin?', '["Smooth muscle cells", "Mesothelial cells — these benign tumors are of mesothelial origin, forming gland-like spaces lined by flat or cuboidal cells; most common paratesticular tumor overall", "Sertoli cells", "Fibroblasts"]', 1, 'Adenomatoid tumor: benign mesothelial neoplasm, most commonly found in the epididymis (also tunica albuginea and paratesticular region). Presents as a small, firm, non-tender paratesticular nodule. Histology: gland-like spaces lined by bland flattened mesothelial cells with no mitoses. No treatment required once diagnosed (scrotal ultrasound typically sufficient).'),
    (v_topic_id, 'A 28-year-old male with a history of cryptorchidism notices a painless left testicular mass. AFP is 12,000 ng/mL, beta-hCG is 200 mIU/mL. CT abdomen shows retroperitoneal lymphadenopathy. What is the stage and initial treatment?', '["Stage I pure seminoma; surveillance", "Stage IIb mixed GCT (NSGCT — elevated AFP rules out pure seminoma); initial treatment: radical inguinal orchiectomy followed by BEP chemotherapy x 3-4 cycles", "Stage III NSGCT treated with surgery alone", "Stage I NSGCT; RPLND alone"]', 1, 'Elevated AFP = non-seminomatous GCT (NSGCT) regardless of histology. Retroperitoneal LN involvement = at least Stage II. Stage IIb = nodes 2-5 cm. Standard: radical inguinal orchiectomy + BEP x 3 cycles (good risk) or 4 cycles (intermediate risk by IGCCCG criteria). Post-chemotherapy residual masses: resect (may contain viable tumor or mature teratoma).')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
